import { useState } from "react";
import { useMutation, useQuery, useQueryClient } from "@tanstack/react-query";
import { Link } from "@tanstack/react-router";
import { TopBar } from "../components/layout";
import { Button, Card, CardHeader, StatusPill } from "../components/ui";
import { createProject, fetchProjects, fetchTickets } from "../lib/api";

const inputCls =
  "rounded-lg border border-line bg-panel px-3 py-2 text-sm text-ink outline-none focus:border-forest";

/** Projects — list from GET /projects, create via POST /projects.
 *  The project key is generated by the API (first letters of the name).
 *  Ticket counts come from GET /tickets, grouped per project. */
export function ProjectsPage() {
  const queryClient = useQueryClient();
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [formError, setFormError] = useState<string | null>(null);

  const projectsQuery = useQuery({
    queryKey: ["projects"],
    queryFn: fetchProjects,
    retry: false,
  });
  const ticketsQuery = useQuery({
    queryKey: ["tickets"],
    queryFn: () => fetchTickets(),
    retry: false,
  });

  const create = useMutation({
    mutationFn: () =>
      createProject({ name: name.trim(), description: description.trim() || undefined }),
    onSuccess: () => {
      setName("");
      setDescription("");
      setFormError(null);
      queryClient.invalidateQueries({ queryKey: ["projects"] });
      queryClient.invalidateQueries({ queryKey: ["boards"] });
    },
    onError: (err) => setFormError(err.message),
  });

  const projects = projectsQuery.data ?? [];
  const ticketCounts = new Map<string, number>();
  for (const t of ticketsQuery.data ?? []) {
    ticketCounts.set(t.projectId, (ticketCounts.get(t.projectId) ?? 0) + 1);
  }

  return (
    <div className="flex min-h-screen flex-col">
      <TopBar title="Projects" />
      <main className="space-y-4 p-6">
        <Card>
          <CardHeader
            title="New project"
            subtitle="A default board (Backlog / To Do / In Progress / Review / Done) is created with it."
          />
          <form
            className="flex flex-wrap items-end gap-3 px-5 py-4"
            onSubmit={(e) => {
              e.preventDefault();
              setFormError(null);
              create.mutate();
            }}
          >
            <label className="block text-sm">
              <span className="font-medium text-ink">Name</span>
              <input
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="e.g. Mobile App"
                className={`${inputCls} mt-1 w-64`}
              />
            </label>
            <label className="block flex-1 text-sm">
              <span className="font-medium text-ink">Description</span>
              <input
                value={description}
                onChange={(e) => setDescription(e.target.value)}
                placeholder="What this project is for"
                className={`${inputCls} mt-1 w-full`}
              />
            </label>
            <Button>Create project</Button>
            {formError ? <p className="w-full text-sm text-red-700">{formError}</p> : null}
          </form>
        </Card>

        {projectsQuery.isPending ? (
          <Card className="p-6 text-sm text-muted">Loading projects…</Card>
        ) : projectsQuery.isError || !projectsQuery.data ? (
          <Card className="p-6 text-sm text-muted">
            The projects API isn't reachable yet — start the API and sign in.
          </Card>
        ) : projects.length === 0 ? (
          <Card className="p-6 text-sm text-muted">
            No projects yet — create your first one above.
          </Card>
        ) : (
          <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
            {projects.map((p) => (
              <Card key={p.id} className="p-5">
                <div className="flex items-start justify-between gap-2">
                  <div>
                    <h3 className="text-sm font-semibold text-ink">{p.name}</h3>
                    <p className="mt-0.5 text-xs text-muted">
                      Key {p.key} · {ticketCounts.get(p.id) ?? 0} ticket
                      {(ticketCounts.get(p.id) ?? 0) === 1 ? "" : "s"}
                    </p>
                  </div>
                  <StatusPill status={p.status} />
                </div>
                {p.description ? (
                  <p className="mt-3 text-sm text-muted">{p.description}</p>
                ) : null}
                <p className="mt-3 text-xs text-muted">
                  Created {new Date(p.createdAt).toLocaleDateString()}
                </p>
                <Link
                  to="/boards"
                  className="mt-4 inline-block rounded-full bg-forest px-4 py-1.5 text-xs font-medium text-white hover:opacity-90"
                >
                  Open board
                </Link>
              </Card>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}
